<style>
.swe-unified .swe-floorplan{background:var(--swe-palette-hex-f5eee5,#f5eee5);border:1px solid var(--swe-palette-hex-d8c7b5,#d8c7b5);border-radius:8px;padding:8px;color:var(--swe-palette-hex-35252a,#35252a)}
.swe-unified .swe-floorplan-header{justify-content:space-between;border-bottom:1px solid var(--swe-palette-hex-ddcfc1,#ddcfc1);padding-bottom:22px;margin-bottom:0}
.swe-unified .swe-floorplan h2{font-family:'Playfair Display',Georgia,serif;font-size:32px;font-weight:400;color:var(--swe-palette-hex-641b2a,#641b2a);letter-spacing:-.03em;margin:4px 0 8px}
.swe-unified .swe-floorplan-eyebrow{display:block;font-size:9px;font-weight:600;color:var(--swe-palette-hex-896344,#896344);letter-spacing:.16em}
.swe-unified .swe-floorplan-header p{color:var(--swe-palette-hex-79685d,#79685d);font-size:11px}
.swe-unified .swe-floorplan-guide{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;padding:18px 0}
.swe-unified .swe-floorplan-legend{display:flex;gap:18px;flex-wrap:wrap}
.swe-unified .swe-floorplan-legend>span{display:inline-flex;align-items:center;gap:7px;font-size:11px;color:var(--swe-palette-hex-574139,#574139)}
.swe-unified .swe-floorplan-legend i{display:inline-block;width:13px;height:13px;border-width:1px;border-style:solid;border-radius:3px}
.swe-unified .swe-floorplan-guide p{margin:0;font-size:10px;color:var(--swe-palette-hex-79685d,#79685d)}
.swe-unified .swe-floorplan-scroll{max-height:480px;max-height:min(480px,65svh);overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding:16px 10px;background:var(--swe-palette-hex-fcf9f4,#fcf9f4);border:1px solid var(--swe-palette-hex-e6d8ca,#e6d8ca);border-radius:6px;scrollbar-color:var(--swe-palette-hex-af8a6b,#af8a6b) var(--swe-palette-hex-eee4da,#eee4da);scrollbar-width:thin}
.swe-unified .swe-floorplan-zone{background:var(--swe-palette-hex-e9dfd3,#e9dfd3);border:1px solid var(--swe-palette-hex-d8c7b5,#d8c7b5);border-radius:6px}
