.swe-unified .swe-floorplan .swe-booth-platinum{background:var(--swe-palette-hex-641b2a,#641b2a);border-color:var(--swe-palette-hex-4d1420,#4d1420);color:var(--swe-palette-hex-fff5ec,#fff5ec)}
.swe-unified .swe-floorplan .swe-booth-gold{background:var(--swe-palette-hex-dbc29c,#dbc29c);border-color:var(--swe-palette-hex-a47b43,#a47b43);color:var(--swe-palette-hex-49321b,#49321b)}
.swe-unified .swe-floorplan .swe-booth-silver{background:var(--swe-palette-hex-dedbd7,#dedbd7);border-color:var(--swe-palette-hex-a49d95,#a49d95);color:var(--swe-palette-hex-443d39,#443d39)}
.swe-unified .swe-floorplan .swe-booth-booked{background:var(--swe-palette-hex-ae7f6a,#ae7f6a);border-color:var(--swe-palette-hex-825541,#825541);color:#fff}
.swe-unified .swe-floorplan .swe-booth-available{background:var(--swe-palette-hex-fffdf8,#fffdf8);border-color:var(--swe-palette-hex-bca58d,#bca58d);border-style:dashed;color:var(--swe-palette-hex-79624f,#79624f)}
